('c1000000-0000-0000-0000-000000000001', 16, '페이징', 'flashcard', '{
  "cards": [
    {"front": "페이징(Paging)이란?", "back": "가상 메모리를 고정 크기의 블록(페이지, Page)으로, 물리 메모리를 같은 크기의 블록(프레임, Frame)으로 나누어 관리하는 기법. 외부 단편화가 없다.", "hint": null},
    {"front": "페이지(Page)와 프레임(Frame)의 차이는?", "back": "페이지: 가상 주소 공간의 고정 크기 블록. 프레임: 물리 주소 공간의 고정 크기 블록. 크기는 동일하며 페이지는 프레임에 매핑된다. 보통 4KB~4MB.", "hint": null},
    {"front": "페이지 테이블(Page Table)의 역할은?", "back": "각 프로세스마다 존재하는 가상 페이지 번호(VPN)와 물리 프레임 번호(PFN) 간의 매핑 정보를 담은 자료구조. 주기억장치에 저장되며 OS가 관리한다.", "hint": null},
    {"front": "페이지 테이블 엔트리(PTE)에 포함되는 정보는?", "back": "① 프레임 번호(PFN) ② 유효 비트(Valid/Present bit): 물리 메모리 상주 여부 ③ 보호 비트(Protection bit): 읽기/쓰기/실행 권한 ④ 참조 비트(Reference bit) ⑤ 수정 비트(Dirty bit)", "hint": null},
    {"front": "내부 단편화(Internal Fragmentation)와 페이징의 관계는?", "back": "페이징에서 프로세스 크기가 페이지 크기의 배수가 아니면 마지막 페이지의 일부가 낭비된다. 이를 내부 단편화라 한다. 페이지 크기가 클수록 내부 단편화 심화.", "hint": null}
  ]
}', 420),

('c1000000-0000-0000-0000-000000000001', 17, 'TLB', 'quiz', '{
  "questions": [
    {"question": "TLB(Translation Lookaside Buffer)의 역할은?", "code": null, "options": ["페이지 테이블의 최근 항목을 캐싱하여 주소 변환 속도를 높인다", "주기억장치의 데이터를 캐싱하여 접근 속도를 높인다", "디스크 I/O를 캐싱하여 입출력 속도를 높인다", "명령어를 캐싱하여 인출 속도를 높인다"], "correct_index": 0, "explanation": "TLB는 MMU 내의 고속 캐시로, 최근에 사용된 가상 페이지 번호(VPN) → 물리 프레임 번호(PFN) 변환 결과를 저장한다. TLB 히트 시 메모리 접근 없이 즉시 변환이 가능하다."},
    {"question": "TLB 미스(TLB Miss)가 발생했을 때의 처리 과정은?", "code": null, "options": ["주기억장치의 페이지 테이블에서 변환 정보를 가져와 TLB에 적재한다", "페이지 폴트 처리 루틴이 실행된다", "프로세스가 종료된다", "운영체제가 디스크에서 페이지를 읽어온다"], "correct_index": 0, "explanation": "TLB 미스 시 MMU(또는 OS)가 주기억장치의 페이지 테이블을 참조하여 변환 정보를 찾고 TLB에 적재한다. 페이지 자체가 없으면 그 후 페이지 폴트가 발생한다."},
    {"question": "문맥 교환(Context Switch) 시 TLB 처리 방법으로 올바른 것은?", "code": null, "options": ["TLB를 무효화(Flush)하거나 ASID로 프로세스를 구분한다", "TLB를 디스크에 저장한다", "TLB를 다음 프로세스가 그대로 사용한다", "TLB를 새 프로세스의 페이지 테이블로 교체한다"], "correct_index": 0, "explanation": "문맥 교환 시 이전 프로세스의 TLB 항목이 유효하지 않으므로 전체를 무효화(TLB Flush)하거나, ASID(Address Space ID) 태그를 사용하여 프로세스별로 TLB 항목을 구분한다."},
    {"question": "TLB의 전형적인 히트율(Hit Rate)은?", "code": null, "options": ["99% 이상", "50~70%", "70~90%", "90~95%"], "correct_index": 0, "explanation": "지역성 원리에 의해 TLB의 히트율은 일반적으로 99% 이상으로 매우 높다. TLB 크기는 수십~수백 개 항목으로 작지만 효과는 매우 크다."},
    {"question": "2단계 페이지 테이블(Two-Level Page Table)을 사용하는 이유는?", "code": null, "options": ["페이지 테이블 자체가 차지하는 메모리를 줄이기 위해", "TLB 히트율을 높이기 위해", "페이지 폴트 처리 속도를 높이기 위해", "주소 변환 속도를 높이기 위해"], "correct_index": 0, "explanation": "단일 페이지 테이블은 모든 가상 주소 공간에 대한 항목을 유지해야 하므로 크기가 매우 크다. 2단계(계층적) 페이지 테이블은 실제 사용 중인 부분만 물리 메모리에 유지하여 메모리를 절약한다."}
  ]
}', 540),

('c1000000-0000-0000-0000-000000000001', 18, 'I/O 방식', 'quiz', '{
  "questions": [
    {"question": "프로그램 I/O(Programmed I/O)의 특징은?", "code": null, "options": ["CPU가 I/O 장치의 상태를 계속 폴링하며 대기한다", "I/O 완료 시 인터럽트로 CPU에 통보한다", "I/O 장치가 직접 메모리에 접근하여 데이터를 전송한다", "채널 프로세서가 I/O를 처리한다"], "correct_index": 0, "explanation": "프로그램 I/O(폴링 방식)는 CPU가 I/O 장치의 준비 상태를 반복 확인(busy-waiting)하므로 CPU 자원이 낭비된다. 단순하지만 비효율적이다."},
